const input = $input.first().json;
if (!input.headers?.['x-workflow-token'] || input.headers['x-workflow-token'] !== $env.N8N_WEBHOOK_TOKEN) throw new Error('Unauthorized workflow trigger.');
const body = input.body ?? {};
for (const key of ['request_id', 'question_id', 'site_key', 'workflow_key', 'workflow_version']) { if (!body[key]) throw new Error(`Missing ${key}.`); }
return [{ json: body }];

const context = $input.first().json.context;
const system = `You classify one ecommerce product question before drafting a reply. Return JSON only with: intents (1-4 keys selected only from available_policies), customer_language (ISO 639-1), country_code (explicit destination only or null), event_date (explicit unambiguous YYYY-MM-DD only or null), requested_currency, requested_language, requires_private_reply, unmatched_requests, summary. Split multiple requests. Never invent facts. Existing-order status is private. Use ask_pockets for whether the item includes pockets and request_add_pockets when the customer asks whether pockets can be added. A combined pockets question may select both. Use request_custom_color when the customer asks whether an item can be made in a requested color, including equivalent questions in languages other than English. Do not use request_custom_length unless the customer explicitly asks to change a garment length or gives a length measurement.`;
return [{ json: { system_prompt: system, user_prompt: JSON.stringify(context) } }];

const context = $('Start Draft Request').first().json.context;
const resolved = $('Resolve Product Order and Live Facts').first().json;
const policies = $input.first().json.data;
const system = `Write a customer-service draft for a public ecommerce product Q&A. Return JSON only: answer_en, confidence (0-1), unresolved_facts, safety_flags. Use only supplied current facts and verified policies. Lead with the direct answer. Be concise: target at most 60 words for a simple question and never exceed 180 words. Answer only what the customer asked; policy documents may contain related rules that must not be volunteered. Do not repeat the full product title or product identifier, and do not restate the product type when the question already identifies it. Do not add greetings, filler, internal reasoning, policy names, API details, or a generic contact-us paragraph. Do not discuss returns, sizing, fees, or lead time unless the customer explicitly asked about them. Do not turn a missing field into a negative fact unless a verified policy defines the default for that product type. Do not promise delivery, availability, customization, refunds, or payment outcomes without explicit fact and policy support. Never disclose customer or order identifiers. Existing-order questions must be private and blocked when no authorized order fact is supplied. For custom-color requests: distinguish listed colors from verified manufacturing capability; if the requested color is not listed and no factory result is supplied, say feasibility is not confirmed rather than saying it is unavailable, then give only the verified next step. Do not enumerate all other colors unless asked. Do not ask the customer to repeat a color already stated or continue the discussion in public Q&A. For pockets, follow the verified default and silhouette policies even when the product snapshot has no pocket field; keep the response concise and omit the product title and identifier.`;
const user = JSON.stringify({ question: context.question, product_sn: context.product_sn, customer_language: resolved.plan.customer_language, intents: resolved.plan.intents, unmatched_requests: resolved.plan.unmatched_requests, facts: resolved.facts, missing_facts: resolved.missing, safety_flags: resolved.safety_flags, recommended_visible: resolved.recommended_visible, policies, reply_style: context.reply_style });
return [{ json: { system_prompt: system, user_prompt: user } }];

const plan = $('Resolve Product Order and Live Facts').first().json.plan;
const draft = $input.first().json.output;
const system = `Translate the supplied English customer-service draft into target_language. Return JSON only: answer_localized. Preserve meaning, factual limits, brevity, product numbers, links, and safety wording. Do not add information. If target_language is en, return the English text unchanged.`;
return [{ json: { system_prompt: system, user_prompt: JSON.stringify({ target_language: plan.customer_language, answer_en: draft.answer_en }) } }];

const context = $('Start Draft Request').first().json.context;
const resolved = $('Resolve Product Order and Live Facts').first().json;
const policies = $('Load Verified Policies').first().json.data;
const generated = $('Generate English Draft').first().json.output;
const translated = $input.first().json.output;
const system = `Act only as a safety, factuality, policy, completeness, and customer-tone reviewer. Do not rewrite the answer. Return JSON only with: approved, must_block, problems, repair_instructions, confidence, safety_flags. Check every independent customer request, supplied facts, verified policies, privacy, unresolved placeholders, unnecessary product title or identifier repetition, generic contact referrals, unsupported promises, and concise warm tone. A simple answer should normally be about 60 English words and two to four sentences. If a safe answer is impossible because an essential current fact or verified policy is missing, set must_block=true. Set approved=false whenever repair is required.`;
const user = JSON.stringify({ question: context.question, product_name: resolved.facts?.product?.name ?? null, plan: resolved.plan, facts: resolved.facts, missing_facts: resolved.missing, pre_generation_safety_flags: resolved.safety_flags, recommended_visible: resolved.recommended_visible, policies, answer_en: generated.answer_en, answer_localized: translated.answer_localized, generated_unresolved_facts: generated.unresolved_facts, generated_safety_flags: generated.safety_flags, reply_style: context.reply_style });
return [{ json: { system_prompt: system, user_prompt: user } }];

const review = $input.first().json;
const context = $('Start Draft Request').first().json.context;
const resolved = $('Resolve Product Order and Live Facts').first().json;
const answer = $('Generate English Draft').first().json.output?.answer_en ?? '';
const policies = $('Load Verified Policies').first().json.data ?? [];
const contactPattern = /\b(?:contact(?:ing)?\s+(?:us|our\s+(?:team|support|customer\s+service))|email\s+us|reach\s+(?:out\s+to\s+)?us)\b|\bsupport@[a-z0-9.-]+\.[a-z]{2,}\b/i;
const policyAllowsContact = contactPattern.test(JSON.stringify(policies));
const productName = resolved.facts?.product?.name ?? '';
const repeatsProductName = productName.length >= 5 && answer.toLocaleLowerCase().includes(productName.toLocaleLowerCase());
const repeatsProductSn = context.product_sn && new RegExp(`\\b${String(context.product_sn).replace(/[.*+?^${}()|[\\]\\]/g, '\\$&')}\\b`, 'i').test(answer);
const problems = [...(review.output?.problems ?? [])];
let instructions = [...(review.output?.repair_instructions ?? [])];
if (!policyAllowsContact) instructions = instructions.filter(instruction => !contactPattern.test(String(instruction)));
if (contactPattern.test(answer) && !policyAllowsContact) {
  problems.push('The answer adds a generic contact referral that is not required by the selected policy.');
  instructions.push('Remove the generic contact or email referral and answer only with the supplied product facts and verified policy.');
}
if (repeatsProductName || repeatsProductSn) {
  problems.push('The answer unnecessarily repeats the product title or identifier.');
  instructions.push('Remove the product title and identifier because the product is already clear from the question context.');
}
const requiresRepair = problems.length > (review.output?.problems ?? []).length || repeatsProductName || repeatsProductSn || (contactPattern.test(answer) && !policyAllowsContact);
return [{ json: { ...review, output: { ...review.output, approved: requiresRepair ? false : review.output?.approved, problems: [...new Set(problems)], repair_instructions: [...new Set(instructions)] } } }];

const review = $input.first().json;
const generated = $('Generate English Draft').first().json.output;
const translated = $('Translate to Target Language').first().json.output;
return [{ json: { output: { approved: true, must_block: review.output.must_block === true, problems: review.output.problems ?? [], repair_summary: null, final_answer_en: generated.answer_en, final_answer_localized: translated.answer_localized, confidence: review.output.confidence ?? generated.confidence, safety_flags: review.output.safety_flags ?? [] }, usage: { reviewer: review.usage }, request_id: review.request_id } }];

const context = $('Start Draft Request').first().json.context;
const resolved = $('Resolve Product Order and Live Facts').first().json;
const policies = $('Load Verified Policies').first().json.data;
const generated = $('Generate English Draft').first().json.output;
const translated = $('Translate to Target Language').first().json.output;
const review = $input.first().json.output;
const system = `Repair the supplied draft exactly once using the review instructions. Return JSON only with: answer_en, answer_localized, repair_summary, confidence, safety_flags. Preserve supplied facts and verified policy limits. Do not add new facts, promises, product titles, identifiers, generic contact referrals, or unresolved placeholders. Keep English and localized answers semantically equivalent.`;
return [{ json: { system_prompt: system, user_prompt: JSON.stringify({ question: context.question, plan: resolved.plan, facts: resolved.facts, missing_facts: resolved.missing, policies, answer_en: generated.answer_en, answer_localized: translated.answer_localized, review }) } }];

const context = $('Start Draft Request').first().json.context;
const resolved = $('Resolve Product Order and Live Facts').first().json;
const policies = $('Load Verified Policies').first().json.data;
const repaired = $input.first().json.output;
const system = `Perform the final review after one repair. Do not repair again. Return JSON only with: approved, must_block, problems, repair_summary, final_answer_en, final_answer_localized, confidence, safety_flags. Approve only if every request is covered, all claims follow supplied facts and verified policies, privacy is safe, English and localized answers match, and the response is concise and natural. If anything remains unsafe or materially incomplete, set approved=false and must_block=true while preserving the repaired answer for human review.`;
return [{ json: { system_prompt: system, user_prompt: JSON.stringify({ question: context.question, plan: resolved.plan, facts: resolved.facts, missing_facts: resolved.missing, policies, repaired_answer: repaired }) } }];

const review = $input.first().json;
const context = $('Start Draft Request').first().json.context;
const resolved = $('Resolve Product Order and Live Facts').first().json;
const answer = review.output?.final_answer_en ?? '';
const policies = $('Load Verified Policies').first().json.data ?? [];
const contactPattern = /\b(?:contact(?:ing)?\s+(?:us|our\s+(?:team|support|customer\s+service))|email\s+us|reach\s+(?:out\s+to\s+)?us)\b|\bsupport@[a-z0-9.-]+\.[a-z]{2,}\b/i;
const productName = resolved.facts?.product?.name ?? '';
const unsupportedContactReferral = contactPattern.test(answer) && !contactPattern.test(JSON.stringify(policies));
const repeatsProductName = productName.length >= 5 && answer.toLocaleLowerCase().includes(productName.toLocaleLowerCase());
const repeatsProductSn = context.product_sn && new RegExp(`\\b${String(context.product_sn).replace(/[.*+?^${}()|[\\]\\]/g, '\\$&')}\\b`, 'i').test(answer);
if (!unsupportedContactReferral && !repeatsProductName && !repeatsProductSn) return [{ json: review }];
const problems = [...(review.output?.problems ?? [])];
const safetyFlags = [...(review.output?.safety_flags ?? [])];
if (unsupportedContactReferral) {
  problems.push('The repaired answer still adds a generic contact referral that is not required by the selected policy.');
  safetyFlags.push('Unsupported generic contact referral remained after the single repair.');
}
if (repeatsProductName || repeatsProductSn) {
  problems.push('The repaired answer still repeats the product title or identifier.');
  safetyFlags.push('Product identity repetition remained after the single repair.');
}
return [{ json: { ...review, output: { ...review.output, approved: false, must_block: true, problems: [...new Set(problems)], safety_flags: [...new Set(safetyFlags)] } } }];
